            else:
                out.append(" ")
            i += 1
        elif state == "block":
            if c == "*" and i + 1 < n and src[i + 1] == "/":
                state = "code"; i += 2; out.append("  ")
            else:
                out.append("\n" if c == "\n" else " "); i += 1
        elif state == "str":
            if c == "\\":
                out.append("  "); i += 2; continue
            if c == '"':
                state = "code"; i += 1; out.append(" "); continue
            if c == "\n":
                raise ValueError("unterminated string")
            out.append(" "); i += 1
